head.script:
// =============================================================================
/**
 * mgt 업무 모듈에서 추출한 업무공통(KRX 고유) 함수.
 * 종목검색 / 로그저장 / 데이터셋 보조 / UI·메시지.
 * 분석·트래킹(trk*) 함수는 trk.xml($c.trk)로 분리하였다.
 * 함수명은 camelCase 로 표준화하고, 각 JSDoc 에 AS-IS 원본명을 병기한다.
 *
 * @author Inswave Systems
 * @class mgt
 * @namespace $c.mgt
 */
// =============================================================================

scwin.onpageload = function () {

};

// -----------------------------------------------------------------------------
// 1. 종목검색 (origin: stockSearch.xml)
// -----------------------------------------------------------------------------

// 종목검색 상태 변수
scwin.stSearchId = "";
scwin.stSearchNm = "";
scwin.stSearchIsurId = "";
scwin.stSearchIsurNm = "";
scwin.stSearchId_js = "";
scwin.stSearchNm_js = "";
scwin.stSearchIsurId_js = "";
scwin.stSearchIsurNm_js = "";

/**
 * @method
 * @name jongmokSearchReset
 * @description 종목검색 관련 상태 변수를 모두 초기화한다.
 * (AS-IS: JongmokSearch_Reset, origin: stockSearch.xml)
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.mgt.jongmokSearchReset();
 */
scwin.jongmokSearchReset = function () {
    scwin.stSearchId = "";
    scwin.stSearchNm = "";
    scwin.stSearchIsurId = "";
    scwin.stSearchIsurNm = "";
    scwin.stSearchId_js = "";
    scwin.stSearchNm_js = "";
    scwin.stSearchIsurId_js = "";
    scwin.stSearchIsurNm_js = "";
    scwin.stSearchKind = "";
    scwin.stSearchMarket = "";
    scwin.stSearchOpt = "";
};

/**
 * @method
 * @name jongmokSearchRtn
 * @description 종목검색 결과(코드/명)를 호출 화면으로 반환한다. (주식·선물용)
 * (AS-IS: JongmokSearch_Rtn, origin: stockSearch.xml)
 * @param {String} sval1 종목 코드
 * @param {String} sval2 종목 명
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.mgt.jongmokSearchRtn("005930", "삼성전자");
 */
scwin.jongmokSearchRtn = function (sval1, sval2) {
    if (scwin.stSearchId_js === "") {
        stSearchId.setValue(sval1);
        if (scwin.stSearchNm !== "") {
            stSearchNm.setValue(sval2);
        }
    } else {
        scwin.stSearchId_js = sval1;
        scwin.stSearchNm_js = sval2;
    }
};

/**
 * @method
 * @name jongmokSearchRtn2
 * @description 종목검색 결과(코드/명 + 발행사 정보)를 호출 화면으로 반환한다. (ELW·수익증권용)
 * (AS-IS: JongmokSearch_Rtn2, origin: stockSearch.xml)
 * @param {String} sval1 종목 코드
 * @param {String} sval2 종목 명
 * @param {String} sval3 발행사 코드
 * @param {String} sval4 발행사 명
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.mgt.jongmokSearchRtn2(code, name, isurId, isurNm);
 */
scwin.jongmokSearchRtn2 = function (sval1, sval2, sval3, sval4) {
    if (scwin.stSearchId_js === "") {
        stSearchId.setValue(sval1);
        if (scwin.stSearchNm !== "") stSearchNm.setValue(sval2);
        if (scwin.stSearchIsurId !== "") stSearchIsurId.setValue(sval3);
        if (scwin.stSearchIsurNm !== "") stSearchIsurNm.setValue(sval4);
    } else {
        scwin.stSearchId_js = sval1;
        scwin.stSearchNm_js = sval2;
        scwin.stSearchIsurId_js = sval3;
        scwin.stSearchIsurNm_js = sval4;
    }
};

// -----------------------------------------------------------------------------
// 2. 로그 저장 (origin: mgt.xml) — 레거시 XHR 기반. 신규 화면은 $c.sbm 사용 권장.
// -----------------------------------------------------------------------------

/**
 * @method
 * @name createXmlObj4LogSave
 * @description 로그저장 요청용 XMLHttpRequest 객체를 생성한다.
 * (AS-IS: createXMLObj4LogSave, origin: mgt.xml)
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.mgt.createXmlObj4LogSave();
 */
scwin.createXmlObj4LogSave = function () {
    if (window.XMLHttpRequest) {
        scwin.xmlHttp4LogSave = new XMLHttpRequest();
    } else if (window.ActiveXObject) {
        scwin.xmlHttp4LogSave = new ActiveXObject("Microsoft.XMLHTTP");
    }
};

/**
 * @method
 * @name startLogSave
 * @description 화면 ID/처리구분으로 로그저장 요청을 비동기 전송한다.
 * (AS-IS: startLogSave, origin: mgt.xml)
 * @param {String} ver1 화면 ID (SCREN_ID)
 * @param {String} ver2 화면 처리구분 코드 (SCREN_PROCES_TP_CD)
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.mgt.startLogSave("MGT0101", "R");
 */
scwin.startLogSave = function (ver1, ver2) {
    const url = "/common/logSaveAct.jsp?SCREN_ID=" + ver1 + "&SCREN_PROCES_TP_CD=" + ver2;
    scwin.xmlHttp4LogSave.onreadystatechange = scwin.chkStats4LogSave;
    scwin.xmlHttp4LogSave.open("GET", url, true);
    scwin.xmlHttp4LogSave.send(null);
};

/**
 * @method
 * @name chkStats4LogSave
 * @description 로그저장 XHR 응답 상태를 점검하고 완료 시 결과를 처리한다. (onreadystatechange 콜백)
 * (AS-IS: chkStats4LogSave, origin: mgt.xml)
 * @returns {void}
 * @hidden N
 * @exception
 * @example
 */
scwin.chkStats4LogSave = function () {
    if (scwin.xmlHttp4LogSave.readyState === 4 && scwin.xmlHttp4LogSave.status === 200) {
        scwin.viewParameter4LogSave();
    }
};

/**
 * @method
 * @name viewParameter4LogSave
 * @description 로그저장 응답(result 노드) 값을 확인한다. (alert4LogSave 가 true 일 때 alert)
 * (AS-IS: viewParameter4logSave, origin: mgt.xml)
 * @returns {void}
 * @hidden N
 * @exception
 * @example
 */
scwin.viewParameter4LogSave = function () {
    const xmlDoc = scwin.xmlHttp4LogSave.responseXML;
    const node = xmlDoc.getElementsByTagName("result");
    if (scwin.alert4LogSave) {
        alert(node[0].childNodes[0].nodeValue);
    }
};

/**
 * @method
 * @name doLogSave
 * @description 로그저장 전체 흐름을 실행한다(객체 생성 → 전송).
 * (AS-IS: doLogSave, origin: mgt.xml)
 * @param {String} ver1 화면 ID
 * @param {String} ver2 화면 처리구분 코드
 * @param {Boolean} ver3 true 면 응답을 alert 로 표시
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.mgt.doLogSave("MGT0101", "R");
 */
scwin.doLogSave = function (ver1, ver2, ver3) {
    scwin.createXmlObj4LogSave();
    if (ver3) scwin.alert4LogSave = true;
    scwin.startLogSave(ver1, ver2);
};

// -----------------------------------------------------------------------------
// 3. 데이터셋 보조 (origin: mgt.xml) — Gauce DataSet API 기반.
// -----------------------------------------------------------------------------

/**
 * @method
 * @name cfParseFeature
 * @description feature 문자열("k1=v1,k2=v2")을 파싱해 값/타입 배열에 채운다. (copyDataSet 보조)
 * (AS-IS: cfParseFeature, origin: mgt.xml)
 * @param {String} features "name=value" 콤마 구분 옵션 문자열
 * @param {Array} fNameArray 옵션 이름 배열
 * @param {Array} fValueArray 값 배열(결과가 채워짐)
 * @param {Array} fTypeArray 타입 배열("string"|"number"|"boolean")
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.mgt.cfParseFeature("rowCnt=10", names, values, types);
 */
scwin.cfParseFeature = function (features, fNameArray, fValueArray, fTypeArray) {
    if (features == null) {
        return;
    }
    const featureArray = features.split(",");
    for (let i = 0; i < featureArray.length; i++) {
        const featurePair = $c.str.trim(featureArray[i]).split("=");
        for (let j = 0; j < fNameArray.length; j++) {
            if (featurePair[0] === fNameArray[j]) {
                switch (fTypeArray[j]) {
                    case "string":
                        fValueArray[j] = featurePair[1];
                        break;
                    case "number":
                        fValueArray[j] = Number(featurePair[1]);
                        break;
                    case "boolean":
                        const v = (featurePair[1] || "").toUpperCase();
                        fValueArray[j] = (v === "YES" || v === "TRUE" || featurePair[1] === "1");
                        break;
                }
            }
        }
    }
};

/**
 * @method
 * @name copyDataSetHeader
 * @description 원본 DataSet 의 컬럼 헤더(id/type/size/property)를 대상 DataSet 으로 복사한다.
 * (AS-IS: CopyDataSetHeader, origin: mgt.xml)
 * @param {Object} oOriginDataSet 원본 DataSet
 * @param {Object} oTargetDataSet 대상 DataSet
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.mgt.copyDataSetHeader(dsA, dsB);
 */
scwin.copyDataSetHeader = function (oOriginDataSet, oTargetDataSet) {
    let dsHeader = "";
    for (let i = 1; i <= oOriginDataSet.getTotalCol(); i++) {
        const colId = oOriginDataSet.ColumnID(i);
        const colIndex = oOriginDataSet.ColumnIndex(colId);
        const colSize = oOriginDataSet.ColumnSize(colIndex);
        const colDec = oOriginDataSet.ColumnDec(colIndex);

        // column type: 1 String, 2 Integer, 3 Decimal, 4 Date, 5 URL, 9 BIGINT
        let colType;
        switch (oOriginDataSet.ColumnType(colIndex)) {
            case 1: colType = "String"; break;
            case 2: colType = "Integer"; break;
            case 3: colType = "Decimal"; break;
            case 4: colType = "Date"; break;
            case 5: colType = "URL"; break;
            case 9: colType = "BIGINT"; break;
            default: colType = ""; break;
        }

        // column property: 0 NORMAL, 1 CONSTANT, 2 KEYVALUE
        let colProp;
        switch (oOriginDataSet.ColumnProp(i)) {
            case 0: colProp = "NORMAL"; break;
            case 1: colProp = "CONSTANT"; break;
            case 2: colProp = "KEYVALUE"; break;
            default: colProp = ""; break;
        }

        if (colType === "Decimal") {
            dsHeader += colId + ":" + colType + "(" + colSize + "." + colDec + "):" + colProp + ",";
        } else {
            dsHeader += colId + ":" + colType + "(" + colSize + "):" + colProp + ",";
        }
    }
    dsHeader = dsHeader.substr(0, dsHeader.length - 1);
    oTargetDataSet.SetDataHeader(dsHeader);
};

/**
 * @method
 * @name copyDataSet
 * @description 원본 DataSet 의 데이터를 대상 DataSet 으로 복사한다. (옵션: copyHeader/resetStatus/rowFrom/rowCnt)
 * (AS-IS: CopyDataSet, origin: mgt.xml)
 * @param {Object} oOriginDataSet 원본 DataSet
 * @param {Object} oTargetDataSet 대상 DataSet
 * @param {String} features 옵션 문자열(예: "copyHeader=true,rowCnt=10")
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.mgt.copyDataSet(dsA, dsB, "resetStatus=true");
 */
scwin.copyDataSet = function (oOriginDataSet, oTargetDataSet, features) {
    const featureNames = ["copyHeader", "resetStatus", "rowFrom", "rowCnt"];
    const featureValues = [true, true, 1, oOriginDataSet.getTotalRow()];
    const featureTypes = ["boolean", "boolean", "number", "number"];
    if (features != null) {
        scwin.cfParseFeature(features, featureNames, featureValues, featureTypes);
    }
    const copyHeader = featureValues[0];
    const resetStatus = featureValues[1];
    const rowFrom = featureValues[2];
    const rowCnt = featureValues[3];

    if (copyHeader === true) {
        scwin.copyDataSetHeader(oOriginDataSet, oTargetDataSet);
    }
    oTargetDataSet.ClearData();
    if (oOriginDataSet.getTotalRow() > 0) {
        const temp = oTargetDataSet.dataid; // ImportData 시 dataid 가 지워지는 것 방지
        oTargetDataSet.ImportData(oOriginDataSet.ExportData(rowFrom, rowCnt, true));
        oTargetDataSet.dataid = temp;
        if (resetStatus === true) {
            oTargetDataSet.ResetStatus();
        }
    }
};

// -----------------------------------------------------------------------------
// 4. UI / 메시지 (origin: mgt.xml, common.xml)
// -----------------------------------------------------------------------------

/**
 * @method
 * @name comboCbDataSetPeriod
 * @description 기간 선택 콤보(1주일~2년)용 CBData 를 지정한다.
 * (AS-IS: Combo_CBDataSetPeriod, origin: mgt.xml)
 * @param {Object} sval 적용할 콤보 컴포넌트
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.mgt.comboCbDataSetPeriod(cbo_period);
 */
scwin.comboCbDataSetPeriod = function (sval) {
    sval.CBData = "1주일전^1,1개월전^2,3개월전^3,6개월전^4,1년전^5,2년전^6";
};

/**
 * @method
 * @name fillGridHeaderTotalCnt
 * @description 그리드 헤더 패널에 "총건수: N" 을 HTML 로 표시한다.
 * (AS-IS: FillGridHeaderTotalCnt, origin: mgt.xml)
 * @param {Number|String} vRsltCnt 총 건수
 * @param {Object} panelID innerHTML 을 설정할 DOM/패널 엘리먼트
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.mgt.fillGridHeaderTotalCnt(120, document.getElementById("hdr"));
 */
scwin.fillGridHeaderTotalCnt = function (vRsltCnt, panelID) {
    const vTotalArea = "<span style='font-size:9pt; font-family:굴림; color:#212863;'>총건수: </span>"
        + "<span style='font-size:9pt; font-family:굴림; color:#5C8BE0; font-weight:bold'>" + $c.num.formatNumber(vRsltCnt) + "</span>";
    panelID.innerHTML = "<table border='0' cellpadding='0' cellspacing='0' height='22' width='100%'><tr>"
        + "<td align='left' width='2%' nowrap>" + vTotalArea + "</td><td align='center'></td>"
        + "<td align='right' width='30'></td><td align='right' width='2%' nowrap>&nbsp;</td></tr></table>";
};

/**
 * @method
 * @name panelMsg
 * @description 지정 패널 영역에 메시지를 HTML 로 표시한다.
 * (AS-IS: PanelMsg, origin: mgt.xml)
 * @param {Object} panelID innerHTML 을 설정할 DOM/패널 엘리먼트
 * @param {String} msg 표시할 메시지
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.mgt.panelMsg(document.getElementById("msg"), "처리되었습니다.");
 */
scwin.panelMsg = function (panelID, msg) {
    const vTotalArea = "<span style='font-size:9pt; font-family:굴림; color:#5C8BE0; font-weight:bold'>" + msg + "</span>";
    panelID.innerHTML = "<table border='0' cellpadding='0' cellspacing='0' height='22' width='100%'><tr>"
        + "<td align='left' width='2%' nowrap>" + vTotalArea + "</td><td align='center'></td>"
        + "<td align='right' width='30'></td><td align='right' width='2%' nowrap>&nbsp;</td></tr></table>";
};

/**
 * @method
 * @name setFromToDate
 * @description 기간타입(pTp)에 따라 From/To 일자 컴포넌트를 자동 설정한다. (To 가 비면 오늘 기준)
 * (AS-IS: fn_setFromToDate, origin: mgt.xml)
 * @param {Number} pTp 기간타입 (1:1주일 2:1개월 3:3개월 4:6개월 5:1년 6:2년)
 * @param {Object} pObjFrom From 일자 컴포넌트(getValue/setValue 보유)
 * @param {Object} pObjTo To 일자 컴포넌트
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.mgt.setFromToDate(2, cal_from, cal_to);
 */
scwin.setFromToDate = function (pTp, pObjFrom, pObjTo) {
    let vFrom = "";
    let vTo = pObjTo.getValue();
    if ($c.util.isEmpty(vTo)) {
        vTo = $c.date.getServerDateTime("yyyymmdd"); // 값이 없으면 오늘 기준
    }

    switch (Number(pTp)) {
        case 1: vFrom = $c.date.addDate(vTo, -7); break;   // 1주일 전
        case 2: vFrom = $c.date.addMonth(vTo, -1); break;  // 1개월 전
        case 3: vFrom = $c.date.addMonth(vTo, -3); break;  // 3개월 전
        case 4: vFrom = $c.date.addMonth(vTo, -6); break;  // 6개월 전
        case 5: vFrom = $c.date.addYear(vTo, -1); break;   // 1년 전
        case 6: vFrom = $c.date.addYear(vTo, -2); break;   // 2년 전
        default: vFrom = vTo; break;
    }
    pObjFrom.setValue(vFrom);
    pObjTo.setValue(vTo);
};

/**
 * @method
 * @name mdiHelp
 * @description 현재 화면 유형에 맞는 도움말 뷰어를 연다. (프레임 함수 위임)
 * (AS-IS: MdiHelp, origin: common.xml)
 * @param {String} helpType 도움말 유형
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.mgt.mdiHelp("01");
 */
scwin.mdiHelp = function (helpType) {
    $c.frame.path("/").GMdiHelp(helpType);
};
